function expandRoute(path: string, profile: number) { const source = routeProfiles[profile]; return { path, ...source, statuses: [...source.statuses] as readonly number[] }; }
const routeEntries: [string, ReturnType<typeof expandRoute>][] = [];
for (const [id, path, profile] of compactRoutes) { if (id === '$suite') { const methods = (suiteRouteRegistry as Record<string, Record<string, Record<string, boolean>>>)[path][profile]; for (const method of Object.keys(methods)) routeEntries.push([path + '-' + profile + '.' + method, expandRoute('/api/' + path + '-' + profile + '/' + method.replace(/[A-Z]/g, letter => '-' + letter.toLowerCase()), 1)]); } else routeEntries.push([id, expandRoute(path, profile)]); }
export const operationRoutes = Object.fromEntries(routeEntries) as OperationRouteIndex;
